Here is a preliminary React TypeScript page using Mantine 7 components.

```tsx
import React, { useState } from 'react';
import { Text, Paper, Container, Title, Table, Button, TextInput, Textarea } from '@mantine/core';

interface Complaint {
  category: string;
  description: string;
}

const CMSPage: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [category, setCategory] = useState<string>('');
  const [description, setDescription] = useState<string>('');

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    setComplaints([...complaints, { category, description }]);
    setCategory('');
    setDescription('');
  };

  return (
    <Container>
      <Title>Complaint Management System (CMS)</Title>

      <Paper shadow="xs" p="md" mt="md">
        <form onSubmit={handleSubmit}>
          <TextInput
            label="Category"
            value={category}
            onChange={(event) => setCategory(event.target.value)}
            required
          />
          <Textarea
            label="Description"
            value={description}
            onChange={(event) => setDescription(event.target.value)}
            required
          />
          <Button type="submit" mt="md">
            Submit Complaint
          </Button>
        </form>
      </Paper>

      <Paper shadow="xs" p="md" mt="md">
        <Table>
          <thead>
            <tr>
              <th>Category</th>
              <th>Description</th>
            </tr>
          </thead>
          <tbody>
            {complaints.map((complaint, index) => (
              <tr key={index}>
                <td>{complaint.category}</td>
                <td>{complaint.description}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      </Paper>
    </Container>
  );
};

export default CMSPage;
```

This code creates a React component `CMSPage` that displays a title 'Complaint Management System (CMS)', a form to register complaints (category, description), and a table of submitted complaints. The form data is managed by the `useState` hooks. When the form is submitted, the `handleSubmit` function is called, which prevents the default form submission, adds the new complaint to the `complaints` array, and resets the form fields. The table is populated with the `complaints` array data.
